package web

import (
	"crypto/sha256"
	"fmt"
	"testing"
)

func TestWidgetLegacyResourcesRemainOriginalNativeGeneration(t *testing.T) {
	// Captured from the accepted pre-UI-plugin default30 distribution, not
	// generated by the candidate build. Current plugin assets may evolve freely.
	for name, expected := range map[string]string{
		"widget.css":        "e4131798f3d929411505043383c8d385a9bed9cee4c350160c7689bb163a0992",
		"widget-runtime.js": "4ea8b40a5372bc1f967843ae6d77faadefad11b95ac7a35fa5260e8083ce8fe8",
	} {
		raw, err := legacyUI.ReadFile("legacy-ui/v1/" + name)
		if err != nil || fmt.Sprintf("%x", sha256.Sum256(raw)) != expected {
			t.Fatal("historical native widget resource changed", name, err)
		}
	}
}
